import React, { useState } from "react";

export function InputSelect(props) {
  const multiple = props.multiple;
  const required = props.required || false;
  const [searchTerm, setSearchTerm] = useState("");

  // příznak označení prázdné hodnoty
  const emptySelected = multiple ? props.value?.length === 0 : !props.value;
  // příznak objektové struktury položek
  const objectItems = props.enum ? false : true;

  // Filtrování položek podle vyhledávacího textu
  const filteredItems = props.items.filter((item) => {
    const name = objectItems ? item.name : props.enum[item];
    return name.toLowerCase().includes(searchTerm.toLowerCase());
  });

  return (
    <div className="form-group">
      <label>{props.label}:</label>
      <input
        type="text"
        className="form-control mb-2"
        placeholder="Hledat..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
      />
      <select
        required={required}
        className="browser-default form-select"
        multiple={multiple}
        name={props.name}
        onChange={props.handleChange}
        value={props.value}
      >
        {required ? (
          <option disabled value={emptySelected}>
            {props.prompt}
          </option>
        ) : (
          <option key={0} value={emptySelected}>
            ({props.prompt})
          </option>
        )}

        {filteredItems.map((item, index) => (
          <option key={required ? index : index + 1} value={objectItems ? item._id : item}>
            {objectItems ? item.name : props.enum[item]}
          </option>
        ))}
      </select>
    </div>
  );
}

export default InputSelect;
